// src/runtime/nccl_scheduler.cpp: use event-based sync and prioritized streams
void schedule_comm(cudaStream_t comm_stream, cudaStream_t compute_stream) {
  cudaEventRecord(comm_event_, comm_stream);
  // defer kernel launches until comm_event_ signals progress
  cudaStreamWaitEvent(compute_stream, comm_event_, 0);
}

// src/runtime/kvcache.cpp: continuous batching window
void KvCache::push_request(Request&& r) {
  window_.push_back(std::move(r));
  if (window_.size() >= config_.batch_threshold || window_timer_.elapsed_ms() > config_.window_ms) {
    flush_window();
  }
}

